app_css:
.tool-app-traplog { font-family: inherit; margin-inline:auto; }
.tool-app-traplog .tl-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 18px; }
.tool-app-traplog .tl-stat { background: #F0FDF4; border: 1px solid #BBF7D0; border-radius: 10px; padding: 10px 12px; text-align: center; }
.tool-app-traplog .tl-stat span { display: block; font-size: 12px; color: #4B5563; }
.tool-app-traplog .tl-stat strong { font-size: 22px; color: #15803D; }
.tool-app-traplog .tl-cols { display: grid; grid-template-columns: 1fr 1.4fr; gap: 20px; }
@media (max-width: 720px) { .tool-app-traplog .tl-cols { grid-template-columns: 1fr; } .tool-app-traplog .tl-stats { grid-template-columns: repeat(2, 1fr); } }
.tool-app-traplog .tl-h { margin: 0 0 10px; font-size: 16px; color: #111827; }
.tool-app-traplog .tl-form label { display: block; font-size: 13px; color: #374151; margin-bottom: 8px; }
.tool-app-traplog .tl-form input, .tool-app-traplog .tl-form select, .tool-app-traplog .tl-form textarea { width: 100%; box-sizing: border-box; margin-top: 3px; padding: 7px 9px; border: 1px solid #D1D5DB; border-radius: 8px; font-size: 14px; }
.tool-app-traplog .tl-formbtns { display: flex; gap: 8px; margin-top: 6px; }
.tool-app-traplog .tl-btn { background: #15803D; color: #fff; border: none; border-radius: 8px; padding: 9px 16px; font-size: 14px; cursor: pointer; }
.tool-app-traplog .tl-btn:hover { background: #166534; }
.tool-app-traplog .tl-btn-ghost { background: #fff; color: #15803D; border: 1px solid #15803D; }
.tool-app-traplog .tl-filters { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 10px; }
.tool-app-traplog .tl-filters input, .tool-app-traplog .tl-filters select { padding: 7px 9px; border: 1px solid #D1D5DB; border-radius: 8px; font-size: 13px; width: 100%; box-sizing: border-box; }
.tool-app-traplog .tl-list { list-style: none; margin: 0; padding: 0; max-height: 460px; overflow-y: auto; }
.tool-app-traplog .tl-item { border: 1px solid #E5E7EB; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; background: #fff; }
.tool-app-traplog .tl-item .tl-row1 { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.tool-app-traplog .tl-item .tl-client { font-weight: 600; color: #111827; }
.tool-app-traplog .tl-item .tl-date { font-size: 12px; color: #6B7280; white-space: nowrap; }
.tool-app-traplog .tl-item .tl-meta { font-size: 13px; color: #374151; margin-top: 4px; }
.tool-app-traplog .tl-item .tl-sub { font-size: 12px; color: #6B7280; margin-top: 4px; }
.tool-app-traplog .tl-item .tl-actions { margin-top: 6px; display: flex; gap: 10px; }
.tool-app-traplog .tl-item .tl-link { background: none; border: none; color: #15803D; font-size: 13px; cursor: pointer; padding: 0; text-decoration: underline; }
.tool-app-traplog .tl-item .tl-del { color: #B91C1C; }
.tool-app-traplog .tl-empty { color: #6B7280; font-size: 14px; padding: 14px; text-align: center; border: 1px dashed #D1D5DB; border-radius: 10px; }
.tool-app-traplog .tl-export { display: flex; gap: 8px; margin-top: 12px; }
.tool-app-traplog .tl-print { display: none; }
@media print {
  .tool-app-traplog .tl-stats, .tool-app-traplog .tl-cols, .tool-app-traplog .tl-export { display: none !important; }
  .tool-app-traplog .tl-print { display: block !important; }
  .tool-app-traplog .tl-print h2 { font-size: 18px; margin: 0 0 4px; }
  .tool-app-traplog .tl-print p { font-size: 12px; color: #333; margin: 0 0 10px; }
  .tool-app-traplog .tl-print table { width: 100%; border-collapse: collapse; font-size: 11px; }
  .tool-app-traplog .tl-print th, .tool-app-traplog .tl-print td { border: 1px solid #999; padding: 4px 6px; text-align: left; }
  .tool-app-traplog .tl-print th { background: #eee; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var LS_KEY = 'toolapp-traplog-data';
  var editingId = null;
  function uid() { return 'id' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36); }
  function todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + ('0' + (d.getMonth() + 1)).slice(-2) + '-' + ('0' + d.getDate()).slice(-2);
  }
  function load() {
    try {
      var d = JSON.parse(localStorage.getItem(LS_KEY));
      if (d && d.entries) return d;
    } catch (e) {}
    return { entries: [] };
  }
  function save(d) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(d)); } catch (e) {}
  }
  function fmtDate(str) {
    if (!str) return '';
    var p = str.split('-');
    return p.length === 3 ? (parseInt(p[1], 10) + '/' + parseInt(p[2], 10) + '/' + p[0]) : str;
  }
  function filtered(d) {
    var q = $('tl-search').value.trim().toLowerCase();
    var sp = $('tl-filter-species').value;
    var from = $('tl-from').value, to = $('tl-to').value;
    return d.entries.filter(function (e) {
      if (sp && e.species !== sp) return false;
      if (from && e.date < from) return false;
      if (to && e.date > to) return false;
      if (q && ((e.client || '') + ' ' + (e.address || '')).toLowerCase().indexOf(q) < 0) return false;
      return true;
    }).sort(function (a, b) { return b.date < a.date ? -1 : (b.date > a.date ? 1 : 0); });
  }
  function renderStats(d) {
    var cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 29);
    var recent = d.entries.filter(function (e) { return new Date(e.date + 'T00:00:00') >= cutoff; });
    var removed = 0, species = {}, days = {};
    recent.forEach(function (e) {
      removed += parseInt(e.count, 10) || 0;
      if (e.species) species[e.species] = 1;
      days[e.date] = 1;
    });
    $('tl-stat-total').textContent = d.entries.length;
    $('tl-stat-removed').textContent = removed;
    $('tl-stat-species').textContent = Object.keys(species).length;
    $('tl-stat-days').textContent = Object.keys(days).length;
  }
  function renderList(d) {
    var list = $('tl-list');
    var rows = filtered(d);
    if (!rows.length) {
      list.innerHTML = '<li class="tl-empty">No activities match. Log your first control activity to get started.</li>';
      return;
    }
    list.innerHTML = rows.map(function (e) {
      return '<li class="tl-item">' +
        '<div class="tl-row1"><span class="tl-client">' + esc(e.client) + '</span>' +
        '<span class="tl-date">' + esc(fmtDate(e.date)) + '</span></div>' +
        '<div class="tl-meta">' + esc(e.species) + ' &times; ' + esc(String(e.count || 0)) +
        ' &mdash; ' + esc(e.method) + ' &rarr; ' + esc(e.disposition) + '</div>' +
        '<div class="tl-sub">' + esc([e.address, e.phone, e.tech].filter(Boolean).join(' · ')) + '</div>' +
        (e.notes ? '<div class="tl-sub">Note: ' + esc(e.notes) + '</div>' : '') +
        '<div class="tl-actions"><button type="button" class="tl-link" data-edit="' + e.id + '">Edit</button>' +
        '<button type="button" class="tl-link tl-del" data-del="' + e.id + '">Delete</button></div></li>';
    }).join('');
    Array.prototype.forEach.call(list.querySelectorAll('[data-edit]'), function (b) {
      b.addEventListener('click', function () { startEdit(b.getAttribute('data-edit')); });
    });
    Array.prototype.forEach.call(list.querySelectorAll('[data-del]'), function (b) {
      b.addEventListener('click', function () {
        if (!confirm('Delete this log entry?')) return;
        var dd = load();
        dd.entries = dd.entries.filter(function (e) { return e.id !== b.getAttribute('data-del'); });
        save(dd); render();
      });
    });
  }
  function render() {
    var d = load();
    renderStats(d);
    renderList(d);
  }
  function startEdit(id) {
    var d = load();
    var e = null;
    for (var i = 0; i < d.entries.length; i++) if (d.entries[i].id === id) { e = d.entries[i]; break; }
    if (!e) return;
    editingId = id;
    $('tl-date').value = e.date; $('tl-client').value = e.client || '';
    $('tl-address').value = e.address || ''; $('tl-phone').value = e.phone || '';
    $('tl-tech').value = e.tech || ''; $('tl-species').value = e.species || '';
    $('tl-count').value = e.count || 0; $('tl-method').value = e.method || '';
    $('tl-disposition').value = e.disposition || ''; $('tl-notes').value = e.notes || '';
    $('tl-submit').textContent = 'Save changes';
    $('tl-cancel').hidden = false;
    $('tl-form').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
  function cancelEdit() {
    editingId = null;
    $('tl-form').reset();
    $('tl-date').value = todayStr();
    $('tl-submit').textContent = 'Log activity';
    $('tl-cancel').hidden = true;
  }
  $('tl-form').addEventListener('submit', function (ev) {
    ev.preventDefault();
    var d = load();
    var rec = {
      id: editingId || uid(),
      date: $('tl-date').value, client: $('tl-client').value.trim(),
      address: $('tl-address').value.trim(), phone: $('tl-phone').value.trim(),
      tech: $('tl-tech').value.trim(), species: $('tl-species').value,
      count: parseInt($('tl-count').value, 10) || 0, method: $('tl-method').value,
      disposition: $('tl-disposition').value, notes: $('tl-notes').value.trim()
    };
    if (editingId) {
      for (var i = 0; i < d.entries.length; i++) {
        if (d.entries[i].id === editingId) { d.entries[i] = rec; break; }
      }
      cancelEdit();
    } else {
      d.entries.push(rec);
      this.reset();
      $('tl-date').value = todayStr();
    }
    save(d);
    render();
  });
  $('tl-cancel').addEventListener('click', cancelEdit);
  ['tl-search', 'tl-filter-species', 'tl-from', 'tl-to'].forEach(function (id) {
    $(id).addEventListener('input', render);
    $(id).addEventListener('change', render);
  });
  $('tl-csv').addEventListener('click', function () {
    var rows = filtered(load());
    var head = ['date', 'provider_tech', 'client', 'address', 'phone', 'species', 'number_removed', 'control_method', 'disposition', 'notes'];
    var lines = [head.join(',')].concat(rows.map(function (e) {
      return [e.date, e.tech, e.client, e.address, e.phone, e.species, e.count, e.method, e.disposition, e.notes]
        .map(function (v) { return '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; }).join(',');
    }));
    var blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'traplog-export.csv';
    document.body.appendChild(a); a.click();
    setTimeout(function () { document.body.removeChild(a); }, 100);
  });
  $('tl-print').addEventListener('click', function () {
    var rows = filtered(load());
    var area = $('tl-print-area');
    var head = ['Date', 'Provider / Tech', 'Client', 'Address', 'Phone', 'Species', 'Removed', 'Method', 'Disposition'];
    area.innerHTML = '<h2>Daily Control Activity Log</h2><p>Printed ' + esc(todayStr()) +
      ' &middot; ' + rows.length + ' entr' + (rows.length === 1 ? 'y' : 'ies') + '</p>' +
      '<table><thead><tr>' + head.map(function (h) { return '<th>' + h + '</th>'; }).join('') + '</tr></thead><tbody>' +
      rows.map(function (e) {
        return '<tr>' + [fmtDate(e.date), e.tech, e.client, e.address, e.phone, e.species, e.count, e.method, e.disposition]
          .map(function (v) { return '<td>' + esc(v == null ? '' : v) + '</td>'; }).join('') + '</tr>';
      }).join('') + '</tbody></table>';
    window.print();
  });
  $('tl-date').value = todayStr();
  render();
})();
